def custom_sort(numbers):
    """
    Sorts a list of floating-point numbers in descending order using the bubble sort algorithm.

    :param numbers: List of floating-point numbers to be sorted.
    :return: A new list with the numbers sorted in descending order.
    """
    n = len(numbers)
    for i in range(n):
        for j in range(0, n-i-1):
