def deep_copy(d):
    """
    Recursively creates a deep copy of the given dictionary d.

    Args:
    d (dict): The dictionary to be deep copied.

    Returns:
    dict: A deep copy of the input dictionary.
    """
    if isinstance(d, dict):
        new_dict = {}
        for key, value in d.items():
            new_dict[key] = deep_copy(value)
        return new_dict
    elif isinstance(d, list):
        new_list = []
        for item in d:
            new_list.append(deep_copy(item))
        return new_list
    elif isinstance(d, set):
        new_set = set()
        for item in d:
            new_set.add(deep_copy(item))
        return new_set
    elif isinstance(d, tuple):
