def binary_search(arr, x, low=0, high=None):
    """
    Perform a binary search on a sorted list to find the index of a target value.

    Parameters:
    arr (list): A sorted list of integers.
    x (int): The target integer to search for.
    low (int): The starting index of the search range.
    high (int): The ending index of the search range.

    Returns:
    int: The index of the target value in the list, or -1 if the target is not found.
    """
    if high is None:
        high = len(arr) - 1

    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == x:
        return mid
    elif arr[mid] > x:
        return binary_search(arr, x, low, mid - 1)
    else:
        return binary_search(arr, x, mid + 1, high)

