import heapq

def running_median(nums):
    """
    Computes the running median of a stream of numbers.

    :param nums: List[int] - A list of integers representing the stream of numbers.
    :return: List[float] - A list of running medians up to each point in the stream.
    """
    smaller_half = []  # Max heap (use negative for max heap behavior in Python)
    larger_half = []  # Min heap

    medians = []
    for num in nums:
        if not smaller_half or num < -smaller_half[0]:
            heapq.heappush(smaller_half, -num)
        else:
            heapq.heappush(larger_half, num)

        # Balance the heaps
        if len(smaller_half) > len(larger_half) + 1:
            heapq.heappush(larger_half, -heapq.heappop(smaller_half))
        elif len(larger_half) > len(smaller_half):
            heapq.heappush(smaller_half, -heapq.heappop(larger_half))

        # Calculate median
        if len(smaller_half) > len(larger_half):
            medians.append(-smaller_half[0])
        elif len(smaller_half) < len(larger_half):
            medians.append(larger_half[0])
        else:
            medians.append((-smaller_half[0] + larger_half[0]) / 2.0)

    return medians

def is_balanced_parentheses(s):
    """
    Determines if a string of parentheses, brackets, and braces is balanced.

    Args:
    s (str): A string containing only '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    matching_pairs = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_pairs:
            top_element = stack.pop() if stack else '#'
            if matching_pairs[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

