def is_balanced_parentheses(s: str) -> bool:
    """
    Checks if the parentheses, brackets, and braces in the string are balanced.

    :param s: A string containing various characters.
    :return: True if the string is balanced, False otherwise.
    """
    closing_map = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in s:
        if char in closing_map.values():
            stack.append(char)
        elif char in closing_map:
            if not stack or stack[-1] != closing_map[char]:
                return False
            stack.pop()

    return not stack

