    """
    Returns the nth prime number, where n is a positive integer.

    :param n: A positive integer representing the position of the prime number to find.
    :return: The nth prime number.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    count = 0
    candidate = 1

