    """
    Returns a list of all prime factors of the integer n in ascending order.
    If n is 1 or less, returns an empty list.

    :param n: Integer to find prime factors of.
    :return: List of prime factors in ascending order.
    """
    prime_factors = []
    if n <= 1:
        return prime_factors

    while n % 2 == 0:
        prime_factors.append(2)
        n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
