def fibonacci_sequence(n, memo=None):
    """
    Generate the first n numbers of the Fibonacci sequence using recursion with memoization.

    :param n: The number of Fibonacci numbers to generate.
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: A list containing the first n Fibonacci numbers.
    """
    if memo is None:
        memo = {}

    def fib_recursive(k):
        if k in memo:
            return memo[k]
        if k <= 1:
            return k
        memo[k] = fib_recursive(k - 1) + fib_recursive(k - 2)
        return memo[k]

    return [fib_recursive(i) for i in range(n)]

def can_partition(nums):
    """
    Determines if a list of integers can be partitioned into two subsets with equal sum.

    :param nums: List of integers
    :return: True if such a partition exists, False otherwise
    """
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if nums[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]

