def find_max_min(numbers):
    """
    Returns a tuple containing the maximum and minimum values from the list.

    :param numbers: List of integers
    :return: Tuple (max_value, min_value)
    :raises ValueError: If the list is empty
    """
    if not numbers:
        raise ValueError("The list is empty")

    max_val = min_val = numbers[0]

    for number in numbers[1:]:
        if number > max_val:
            max_val = number
        elif number < min_val:
            min_val = number

    return (max_val, min_val)

def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def filter_primes(numbers):
    """Return a list of prime numbers from the given list of integers."""
    return [num for num in numbers if is_prime(num)]

