def sum_of_all_nodes(root):
    """
    Recursively calculates the sum of all node values in a binary tree.

    Parameters:
    root (TreeNode): The root node of the binary tree.

    Returns:
    int: The sum of all node values in the tree.
    """
    if root is None:
        return 0
    return root.val + sum_of_all_nodes(root.left) + sum_of_all_nodes(root.right)

def generate_primes(n):
    """
    Generate a list of prime numbers up to a given number n using the Sieve of Eratosthenes algorithm.

    :param n: The upper limit (inclusive) for generating prime numbers.
    :return: A list of prime numbers up to n.
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

