import json

def parse_json(json_string):
    """
    Parses a JSON string and returns a Python dictionary.

    Parameters:
    json_string (str): A string representing a JSON object.

    Returns:
    dict or None: A dictionary if the JSON string is valid, otherwise None.
    """
    try:
        return json.loads(json_string)
    except json.JSONDecodeError:
        return None

def filter_json_data(data, key):
    """
    Recursively search for all values associated with the specified key in a nested JSON object.

    :param data: A JSON object (dict or list) to search within.
    :param key: A string representing the key to search for.
    :return: A list of values associated with the specified key.
    """
    results = []

    def _search(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == key:
                    results.append(v)
                _search(v)
        elif isinstance(obj, list):
            for item in obj:
                _search(item)

    _search(data)
    return results

def fibonacci_recursive(n):
    """
    Computes the nth Fibonacci number using a simple recursive approach.

    Args:
    n (int): The position in the Fibonacci sequence.

    Returns:
    int: The nth Fibonacci number.
    """
    if n <= 0:
        raise ValueError("Input should be a positive integer.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)

def fibonacci_memoized(n, memo=None):
    """
    Computes the nth Fibonacci number using a memoized recursive approach.

    Args:
    n (int): The position in the Fibonacci sequence.
    memo (dict): A dictionary used to store previously computed Fibonacci numbers.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}

    if n <= 0:
        raise ValueError("Input should be a positive integer.")
    elif n in memo:
        return memo[n]
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        memo[n] = fibonacci_memoized(n - 1, memo) + fibonacci_memoized(n - 2, memo)
        return memo[n]

