def find_max_prime_below(n):
    """Find the largest prime number less than n."""
    if n <= 2:
        return None
    for candidate in range(n-1, 1, -1):
        if is_prime(candidate):
            return candidate
    return None

def is_valid_ipv4(ip: str) -> bool:
    """
    Determines if the given string is a valid IPv4 address.

    :param ip: A string representing the IPv4 address to be validated.
    :return: True if the string is a valid IPv4 address, False otherwise.
    """
    parts = ip.split('.')

    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False

        num = int(part)

        if num < 0 or num > 255:
            return False

        if part != str(num):
            return False

    return True

