import string
from collections import Counter

def read_file(file_path):
    """Reads the contents of the text file and returns it as a string."""
    with open(file_path, 'r') as file:
        return file.read()

def preprocess_text(text):
    """Converts text to lowercase and removes punctuation."""
    text = text.lower()
    text = text.translate(str.maketrans('', '', string.punctuation))
    return text

def count_words(text):
    """Counts the frequency of each word in the text and returns a Counter object."""
    words = text.split()
    return Counter(words)

def get_top_n_words(word_counts, n=10):
    """Returns the top n most common words from the word counts."""
    return word_counts.most_common(n)

def summarize_words_in_file(file_path):
    """Analyzes the text file and prints the top 10 most frequently used words."""
    text = read_file(file_path)
    processed_text = preprocess_text(text)
    word_counts = count_words(processed_text)
    top_words = get_top_n_words(word_counts)

    for word, count in top_words:
        print(f'{word}: {count}')

