    return max(dp)

import math

def calculate_area(shape, **kwargs):
    """
    Calculate the area of a given shape.

    Parameters:
    shape (str): The name of the shape ('rectangle', 'circle', 'triangle').
    **kwargs: Additional keyword arguments required for the shape:
        - For 'rectangle': length, width
        - For 'circle': radius
        - For 'triangle': base, height

    Returns:
    float: The area of the shape.

    Raises:
    ValueError: If the required parameters are not provided or if the shape is unsupported.
    """
    if shape == 'rectangle':
        length = kwargs.get('length')
        width = kwargs.get('width')
        if length is not None and width is not None:
            return length * width
        else:
            raise ValueError("For a rectangle, 'length' and 'width' must be provided.")
    elif shape == 'circle':
        radius = kwargs.get('radius')
        if radius is not None:
            return math.pi * (radius ** 2)
        else:
            raise ValueError("For a circle, 'radius' must be provided.")
    elif shape == 'triangle':
        base = kwargs.get('base')
        height = kwargs.get('height')
        if base is not None and height is not None:
            return 0.5 * base * height
        else:
            raise ValueError("For a triangle, 'base' and 'height' must be provided.")
    else:
        raise ValueError("Unsupported shape. Please choose from 'rectangle', 'circle', or 'triangle'.")

def max_depth(tree):
    """
    Computes the maximum depth of a tree represented as a JSON object.

    :param tree: A dictionary representing the tree structure with a 'children' key.
    :return: An integer representing the maximum depth of the tree.
    """
    if not tree:
        return 0
    if not tree['children']:
        return 1
    children_depths = [max_depth(child) for child in tree['children']]
    return 1 + max(children_depths)

