def is_valid_parentheses(s: str) -> bool:
    """
    Determines if a string of parentheses is valid.

    A string is valid if every opening parenthesis '(' has a corresponding closing parenthesis ')'
    and the pairs are properly nested.

    :param s: A string consisting of '(' and ')'.
    :return: True if the string is valid, False otherwise.
    """
    stack = []
    matching_parentheses = {')': '('}

    for char in s:
        if char in matching_parentheses:
            top_element = stack.pop() if stack else '#'
            if matching_parentheses[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def is_balanced_parentheses(expression):
    """
    Determines if the parentheses in the given expression are balanced.

    :param expression: A string consisting solely of '(' and ')'.
    :return: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

