def max_value_in_tree(root):
    """
    Returns the maximum value in a binary tree.

    :param root: TreeNode, the root of the binary tree
    :return: int, the maximum value in the binary tree
    """
    if root is None:
        return float('-inf')  # Base case, though the problem states root is not None
    left_max = max_value_in_tree(root.left)
    right_max = max_value_in_tree(root.right)
    return max(root.value, left_max, right_max)

def find_smallest_missing_positive(arr):
    """
    Returns the smallest missing positive integer from the given list of integers.

    :param arr: List of integers which may contain negative numbers, zeros, and duplicates.
    :return: The smallest missing positive integer.
    """
    n = len(arr)

    for i in range(n):
        while 1 <= arr[i] <= n and arr[arr[i] - 1] != arr[i]:
            correct_index = arr[i] - 1
            arr[i], arr[correct_index] = arr[correct_index], arr[i]

    for i in range(n):
        if arr[i] != i + 1:
            return i + 1

    return n + 1

def find_target(matrix, target):
    """
    Finds the first occurrence of the target value in a 2D list (matrix).

    Parameters:
    matrix (list of list of int): The 2D list to search within.
    target (int): The target value to find.

    Returns:
    tuple or None: A tuple (row_index, col_index) of the first occurrence of the target,
                   or None if the target is not found.
    """
    for row_index, row in enumerate(matrix):
        for col_index, value in enumerate(row):
            if value == target:
                return (row_index, col_index)
    return None

