def find_largest_prime(n):
    """
    Returns the largest prime number less than or equal to n.
    If no prime number exists, returns None.

    :param n: An integer representing the upper limit.
    :return: The largest prime number less than or equal to n, or None.
    """
    if n < 2:
        return None  # No prime numbers less than 2

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime numbers

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    for num in range(n, 1, -1):
        if is_prime[num]:
            return num

    return None

