def flatten(lst):
    """Recursively flattens a nested list."""
    for elem in lst:
        if isinstance(elem, list):
            yield from flatten(elem)
        else:
            yield elem

def find_common_elements(list1, list2):
    """
    Finds the common elements between two lists, handling nested lists.

    :param list1: First list, may contain nested lists.
    :param list2: Second list, may contain nested lists.
    :return: A sorted list of common elements without duplicates.
    """
    flat_list1 = set(flatten(list1))
    flat_list2 = set(flatten(list2))
    common_elements = flat_list1.intersection(flat_list2)
    return sorted(common_elements)

