def convert_to_title_case(s):
    """
    Transforms a given string into title case, capitalizing the first and last words,
    and other words unless they are small words like "and", "or", "the", "a", "an",
    "in", "on", "at", "to", "with", "of".

    :param s: A string consisting of words separated by spaces.
    :return: A string in title case.
    """
    small_words = {"and", "or", "the", "a", "an", "in", "on", "at", "to", "with", "of"}
    words = s.split()
    title_cased_words = [words[0].capitalize()]  # Always capitalize the first word

    for word in words[1:-1]:
        if word.lower() in small_words:
            title_cased_words.append(word.lower())
        else:
            title_cased_words.append(word.capitalize())

    if len(words) > 1:
        title_cased_words.append(words[-1].capitalize())  # Always capitalize the last word

    return ' '.join(title_cased_words)

def calculate_average(numbers):
    """
    Calculate the average of a list of numbers.

    :param numbers: List of numeric values (integers or floats)
    :return: The average of the numbers, or None if the list is empty
    """
    if not numbers:
        return None
    return sum(numbers) / len(numbers)

def update_inventory(inventory, updates):
    """
    Updates the inventory dictionary with the provided updates.
    If an item does not exist in the inventory, it will be added.
    Positive values in updates increase the inventory, negative values decrease it.

    :param inventory: Dictionary of item names as keys and quantities as values.
    :param updates: Dictionary of item names as keys and quantities to be added or subtracted as values.
    """
    for item, quantity in updates.items():
        if item in inventory:
            inventory[item] += quantity
        else:
            inventory[item] = quantity

def sum_odd_numbers(n):
    """
    Calculate the sum of all odd numbers from 1 to n (inclusive).
    If n is less than 1, return 0.

    :param n: The upper limit of the range to sum odd numbers.
    :return: The sum of all odd numbers from 1 to n.
    """
    if n < 1:
        return 0
    return sum(x for x in range(1, n + 1) if x % 2 != 0)

import csv
import os

def print_high_paid_employees(file_path):
    """
    Reads a CSV file and prints names of employees with a salary greater than 50000.

    Parameters:
    file_path (str): The path to the CSV file.
    """
    if not os.path.exists(file_path):
        print(f"Error: The file '{file_path}' does not exist.")
        return

    try:
        with open(file_path, mode='r', newline='') as file:
            reader = csv.DictReader(file)

            if 'Name' not in reader.fieldnames or 'Salary' not in reader.fieldnames:
                print("Error: The CSV file is malformed. It should have 'Name' and 'Salary' columns.")
                return

            for row in reader:
                try:
                    salary = float(row['Salary'])
                    if salary > 50000:
                        print(row['Name'])
                except ValueError:
                    print(f"Error: The salary value '{row['Salary']}' for employee '{row['Name']}' is malformed.")

    except IOError:
        print(f"Error: An error occurred while reading the file '{file_path}'.")

