def max_depth(root):
    """
    Calculate the maximum depth of a binary tree.

    :param root: TreeNode, the root of the binary tree
    :return: int, the maximum depth of the tree
    """
    if root is None:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))

def count_pixels(image):
    """
    Counts the number of white and black pixels in a binary image.

    Parameters:
    image (list of list of int): A 2D list representing the binary image.

    Returns:
    dict: A dictionary with keys "white_pixels" and "black_pixels" and their respective counts.
    """
    # Flatten the 2D list into a 1D list
    flat_list = [pixel for row in image for pixel in row]

    # Recursive function to count white and black pixels
    def count_recursive(index, white_count, black_count):
        if index == len(flat_list):
            return white_count, black_count
        if flat_list[index] == 1:
            white_count += 1
        else:
