def update_comments(code_comments, code_generator):
    """
    Updates the keys in `code_comments` to their corresponding container names from `code_generator`.
    If two functions share the same container name, their comments are combined into a single string, separated by a newline.

    :param code_comments: Dictionary with function names as keys and comments as values.
    :param code_generator: Generator object yielding unique container names.
    """
    container_dict = {}

    for comment_type, comment in code_comments.items():
        container_name = next(code_generator)
        if container_name in container_dict:
