    Parameters:
    original_price (float): The original price of the item.
    discounted_price (float): The discounted price of the item.

    Returns:
    float: The discount percentage rounded to four decimal places.
    """
    if original_price < 0:
        raise ValueError("Original price cannot be negative.")
    if discounted_price < 0:
        raise ValueError("Discounted price cannot be negative.")
    if original_price == 0:
        return 0.0 if discounted_price == 0 else float('inf')

    discount_percentage = ((original_price - discounted_price) / original_price) * 100
    return round(discount_percentage, 4)

