# Global dictionary to keep track of event registrations
event_registry = {}


def register_for_events(*event_names):
    """
    Decorator to register a function for specified events.
    Supports nested usage to aggregate events from all enclosing decorators.

    :param event_names: Variable number of event names to register.
    :return: Decorated function.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapped_func(*args, **kwargs):
            return func(*args, **kwargs)

        # Retrieve previously registered events for this function
        previously_registered_events = event_registry.get(func.__name__, set())
        # Update the set of events with the new ones from the decorator
        all_events = previously_registered_events | set(event_names)
        # Update the global registry with the combined set of events
        event_registry[func.__name__] = all_events

        return wrapped_func

    return decorator


