def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def validate_data(data):
    """Validate if all lists in the dictionary have the same length and contain only prime numbers."""
    if not data:
        return False  # Consider an empty dictionary as invalid for this context

    list_length = len(next(iter(data.values())))  # Get the length of the first list

    for numbers in data.values():
        if len(numbers) != list_length:
            return False  # Lists have different lengths
        if not all(is_prime(num) for num in numbers):
            return False  # List contains non-prime numbers

    return True  # All lists have the same length and contain only prime numbers

def countDigits(sentence):
    """
    Counts the number of digits in the given sentence without using loops or built-in counting functions.

    :param sentence: A string containing words, punctuation, and digits.
    :return: The total number of digits in the sentence.
    """
    def is_digit(ch):
        return '0' <= ch <= '9'

    def count_recursive(index, count):
        if index == len(sentence):
            return count
        else:
            return count_recursive(index + 1, count + (1 if is_digit(sentence[index]) else 0))

    return count_recursive(0, 0)

