def get_value_from_file(file_contents: str, key: str) -> float or None:
    """
    Parses the given file contents to find the value associated with the specified key.
    Returns the value as a float if the key is found, otherwise returns None.

    :param file_contents: A string representing the contents of a text file with key-value pairs.
    :param key: A string representing the key to search for in the file contents.
    :return: The corresponding floating-point value if the key is found, otherwise None.
    """
    for line in file_contents.splitlines():
        line = line.strip()
        if not line or '=' not in line:
            continue
        line_key, line_value = line.split('=', 1)
        line_key = line_key.strip()
        line_value = line_value.strip()
        if line_key == key:
            try:
                return float(line_value)
            except ValueError:
                return None
