def compute_ceil_max(num1, num2=None):
    """
    Computes the ceiling of num1 if num2 is not provided, otherwise returns the maximum of num1 and num2.

    Parameters:
    num1 (int, float, complex): The first number.
    num2 (int, float, optional): The second number. Defaults to None.

    Returns:
    int, float: The ceiling of num1 or the maximum of num1 and num2.

    Raises:
    NotImplementedError: If num1 is a complex number and num2 is not provided.
    """
    if num2 is None:
        if isinstance(num1, complex):
            raise NotImplementedError("Complex numbers are not supported when num2 is not provided.")

        if isinstance(num1, int):
            ceil_value = num1
        else:
            ceil_value = int(num1)
            if num1 > ceil_value:
                ceil_value += 1
        return ceil_value
    else:
        if num1 > num2:
            return num1
        else:
            return num2

def find_all_values_by_key(data, search_key):
    """
    Recursively searches for all values associated with a given key in a nested dictionary or list.

    Parameters:
    - data: A nested dictionary or list.
    - search_key: A string representing the key to search for.

    Returns:
    - A list of all values associated with the search_key, ignoring case differences.
    """
    search_key = search_key.lower()
    results = []

    def recursive_search(current_data):
        if isinstance(current_data, dict):
            for key, value in current_data.items():
                if key.lower() == search_key:
                    results.append(value)
                recursive_search(value)
        elif isinstance(current_data, list):
            for item in current_data:
                recursive_search(item)

    recursive_search(data)
    return results

