def check_uniformity(lst):
    """
    Determines if a list is uniform across all segments of length k for any k in the range [1, n].

    Parameters:
    lst (list of int): The list of integers to check.

    Returns:
    bool: True if the list is uniform across all segments, False otherwise.
    """
    def is_uniform(sublist):
        return all(x == sublist[0] for x in sublist)

    n = len(lst)
    for k in range(1, n + 1):
        for i in range(n - k + 1):
            if not is_uniform(lst[i:i + k]):
                return False
    return True

