def merge_two_sorted_lists(lst1, lst2):
    """
    Merges two sorted lists into a single sorted list.

    Parameters:
    lst1 (list): The first sorted list.
    lst2 (list): The second sorted list.

    Returns:
    list: A merged sorted list containing all elements from lst1 and lst2.
    """
    if not lst1:
        return lst2
    if not lst2:
        return lst1

    if lst1[0] < lst2[0]:
        return [lst1[0]] + merge_two_sorted_lists(lst1[1:], lst2)
    else:
        return [lst2[0]] + merge_two_sorted_lists(lst1, lst2[1:])

def merge_sorted_lists(lists):
    """
    Merges a list of sorted lists into a single sorted list using recursion.

    Parameters:
    lists (list of list): A list containing sorted sublists.

    Returns:
    list: A single sorted list containing all elements from the input sublists.
    """
    if not lists:
        return []
    if len(lists) == 1:
        return lists[0]

    mid = len(lists) // 2
    left_merged = merge_sorted_lists(lists[:mid])
    right_merged = merge_sorted_lists(lists[mid:])

    return merge_two_sorted_lists(left_merged, right_merged)

def palindrome_checker(s: str) -> bool:
    """
    Determines if the given string is a palindrome, ignoring non-alphanumeric characters and case differences.

    :param s: The input string to check.
    :return: True if the string is a palindrome, False otherwise.
    :raises TypeError: If the input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    cleaned = []
    for char in s:
        if ('a' <= char <= 'z') or ('A' <= char <= 'Z') or ('0' <= char <= '9'):
            cleaned.append(char.lower())

    left, right = 0, len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1

    return True

def encode_string(s, encoding):
    """
    Encodes the given string `s` using the specified `encoding` if `s` contains only ASCII characters
    and the encoding is one of 'utf-8', 'gb2312', or 'latin-1'. Returns the original string otherwise.

    :param s: The string to be encoded.
    :param encoding: The encoding type to use.
    :return: The encoded string or the original string if conditions are not met.
    """
    supported_encodings = ['utf-8', 'gb2312', 'latin-1']

    if encoding not in supported_encodings:
        return s

    if all(ord(c) < 128 for c in s):
        try:
            return s.encode(encoding)
        except UnicodeEncodeError:
            return s
    else:
        return s

