        return placeholder_types[0]
    else:
        return placeholder_types

def find_common_elements(list1, list2):
    """
    Returns a list of elements that are common to both list1 and list2,
    maintaining the order of elements as they appear in list1.
    """
    def has_element(lst, element):
        """
        Checks if an element is present in the list without using 'in'.
        """
        def check(e):
            return e == element
        return any(map(check, lst))

    def remove_first(lst, element):
        """
        Removes the first occurrence of an element from the list.
        """
        def remove(e):
            if e == element:
                remove.element_found = True
            return not (e == element and not remove.element_found)
        remove.element_found = False
        return list(filter(remove, lst))

    def find_common_rec(lst1, lst2, result):
        """
        Recursively finds common elements between lst1 and lst2.
        """
        if not lst1:
            return result
        head = lst1[0]
        tail = lst1[1:]
        if has_element(lst2, head):
            return find_common_rec(tail, remove_first(lst2, head), result + [head])
        else:
            return find_common_rec(tail, lst2, result)

    return find_common_rec(list1, list2, [])

def convert_data(data):
    """
    Recursively converts strings and bytes within a nested data structure to strings.

    Parameters:
    data: The data structure to be converted. Can be of any data type, including nested structures.

    Returns:
    The converted data structure with all strings and bytes decoded to strings.
    If an error occurs during conversion, returns a meaningful error message.
    """
    def _convert(element):
        try:
            if isinstance(element, str):
                return element
            elif isinstance(element, bytes):
                return element.decode('utf-8')
            elif element is None:
                return ""
            elif isinstance(element, dict):
                return {convert_data(k): convert_data(v) for k, v in element.items()}
            elif isinstance(element, (list, tuple)):
                return type(element)(convert_data(item) for item in element)
            else:
                return element
        except Exception as e:
            return f"Error converting {element}: {str(e)}"

    return _convert(data)

import datetime

def calculateElapsedTime(startTime, endTime, granularity):
    """
    Calculate elapsed time from startTime to endTime with specified granularity.

    :param startTime: (int) Unix epoch timestamp marking the start time
    :param endTime: (int) Unix epoch timestamp marking the end time
    :param granularity: (str) Time granularity: 's' for seconds, 'm' for minutes, 'h' for hours, 'd' for days
    :return: (int) Elapsed time in specified units
    """
    if granularity not in ['s', 'm', 'h', 'd']:
        raise ValueError("Granularity must be one of 's', 'm', 'h', 'd'")

    delta = datetime.timedelta(seconds=endTime - startTime)

    if granularity == 's':
        return int(delta.total_seconds())
    elif granularity == 'm':
        return int(delta.total_seconds() / 60)
    elif granularity == 'h':
        return int(delta.total_seconds() / 3600)
    elif granularity == 'd':
        return int(delta.total_seconds() / 86400)

def count_prime_factors(n):
    """
    Returns the count of distinct prime factors of the given integer n.

    :param n: Integer, the number to find distinct prime factors for.
    :return: Integer, count of distinct prime factors.
    """
    count = 0
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            count += 1
            while n % i == 0:
                n //= i
    if n > 2:
        count += 1
    return count

