def count_entities(paragraphs):
    """
    Counts the occurrences of each unique entity across all paragraphs.

    :param paragraphs: List of dictionaries, each containing 'text' and 'entities' keys.
    :return: Dictionary mapping each unique entity to its count.
    """
    entity_count = {}

    for paragraph in paragraphs:
        text = paragraph["text"]
        entities = paragraph["entities"]

        for entity in entities:
            start, end = entity["start"], entity["end"]
            entity_text = text[start:end]

            if entity_text in entity_count:
                entity_count[entity_text] += 1
            else:
                entity_count[entity_text] = 1

    return entity_count

class Word:
    def __init__(self, word, pos, position):
        self.word = word
        self.pos = pos
        self.position = position

def extract_nested_word_info(obj):
    """
    Recursively traverses the nested structure and extracts (word, pos, position) tuples.
    """
    if isinstance(obj, Word):
        yield (obj.word, obj.pos, obj.position)
    elif isinstance(obj, list):
        for item in obj:
            yield from extract_nested_word_info(item)
    elif isinstance(obj, dict):
        for value in obj.values():
            yield from extract_nested_word_info(value)

def extract_word_pos_indices(word_list, word_pos_dict):
    """
    Returns a list of indices from word_pos_dict for each Word object in word_list,
    including nested structures.
    """
    result = []
    for word_tuple in extract_nested_word_info(word_list):
        if word_tuple in word_pos_dict:
            result.append(word_pos_dict[word_tuple])
    return result

