    Parameters:
    head (int or list of int): The head of the logical rule, can be a single integer or a list of integers.

    Returns:
    str: The string representation of the head.
    """
    if isinstance(head, list):
        if 1 in head:
            return ''
        else:
            return ' | '.join('v' + str(atom) for atom in head if atom > 0)
