        elif head > 0:
            return 'v' + str(head)
    return ''

from typing import List, Union

def find_item_indices(desired_items: List[str], available_items: List[str], pad: bool = True) -> List[Union[int, None]]:
    """
    Returns a list of indices from available_items that match the items in desired_items.
    If an item from desired_items is not found in available_items and pad is True, returns None for that item.
    If pad is False, excludes items from desired_items that are not found in available_items.
    """
    indices = []

    for item in desired_items:
        item_indices = [idx for idx, available_item in enumerate(available_items) if available_item == item]

        if item_indices:
            indices.extend(item_indices)
        else:
            if pad:
                indices.append(None)

    return indices

