def calculate_damage(player, weapon, target):
    """
    Calculate the damage dealt by a player using a specific weapon, considering the player's proficiency with the weapon.

    Parameters:
    player (dict): A dictionary containing the player's proficiency with various weapons.
    weapon (dict): A dictionary containing the weapon's name, minimum damage, and maximum damage.
