import json

def process_request(request):
    """
    Processes an HTTP request and extracts relevant parameters based on the request method.

    Args:
        request (dict): A dictionary containing the request details.

    Returns:
        dict: A dictionary containing the extracted parameters or an error message with a status code.
    """
    method = request.get('method', '').upper()
    body = request.get('body', '')
    query_params = request.get('query_params', {})

    try:
        if method == 'GET':
            return query_params

        elif method == 'POST':
            data = json.loads(body)
            filtered_data = {k: v for k, v in data.items() if v is not None and v != ""}
            return filtered_data

        elif method == 'DELETE':
            data = json.loads(body)
            return data

        elif method == 'PATCH':
            pre_existing_data = request.get('pre_existing_data', {})
            data = json.loads(body)
            updates = {k: v for k, v in data.items() if v is not None}
            pre_existing_data.update(updates)
            return pre_existing_data

        else:
            return {"error": "Unsupported HTTP method", "status_code": 405}

    except json.JSONDecodeError:
        return {"error": "Invalid JSON body", "status_code": 400}

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {"error": "Internal server error", "status_code": 500}

def gcd(a, b):
    """Helper function to find GCD of two numbers using the Euclidean algorithm."""
    while b != 0:
        a, b = b, abs(a) % b
    return abs(a)

def gcd_of_array(arr):
    """Function to find the GCD of a list of numbers."""
    if not arr:
        raise ValueError("Array should not be empty")

    current_gcd = abs(arr[0])
    for num in arr[1:]:
        current_gcd = gcd(current_gcd, num)
    return current_gcd

def find_pair_sum(numbers, target, left=None, right=None):
    """
    Recursively finds a pair of indices (i, j) such that numbers[i] + numbers[j] == target.

    :param numbers: List[int] - A sorted list of distinct integers.
    :param target: int - The target sum to find.
    :param left: int - The starting index for the search (default is None).
    :param right: int - The ending index for the search (default is None).
    :return: Tuple[int, int] or None - A tuple of indices if a pair is found, otherwise None.
    """
    if left is None or right is None:
        left, right = 0, len(numbers) - 1

    if left >= right:
        return None

    current_sum = numbers[left] + numbers[right]

    if current_sum == target:
        return (left, right)
    elif current_sum < target:
        return find_pair_sum(numbers, target, left + 1, right)
    else:
        return find_pair_sum(numbers, target, left, right - 1)

def find_fibonacci(n: int, memo: dict = {}) -> int:
    """
    Calculate the nth Fibonacci number using memoization.

    Parameters:
    n (int): Position in the Fibonacci sequence

    Returns:
    int: nth Fibonacci number

    Raises:
    TypeError: If the provided input is not an integer.
    ValueError: If the provided input is negative.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must not be negative.")

    if n in memo:
        return memo[n]

    if n == 0:
        return 0
    elif n == 1:
        return 1

    memo[n] = find_fibonacci(n - 1, memo) + find_fibonacci(n - 2, memo)
    return memo[n]

