def memoize(func):
    """
    Decorator to cache the results of a function to avoid redundant computations.
    """
    cache = {}

    def memoized_func(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result

    return memoized_func


@memoize
def factorial(n):
    """
    Computes the factorial of a non-negative integer n using recursion.
    Utilizes memoization to optimize recursive calls.
    """
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)


