def is_valid_braces_sequence(s):
    """
    Checks if the given string `s` is a valid braces sequence.

    Args:
    s (str): A string containing only '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if `s` is a valid braces sequence, False otherwise.
    """
    stack = []
    braces_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in braces_map.values():
            stack.append(char)
        elif char in braces_map:
            if not stack or braces_map[char] != stack.pop():
                return False
        else:
            return False

    return not stack

