def count_prime_numbers(n):
    """
    Returns the count of all prime numbers less than or equal to a given number n using the Sieve of Eratosthenes algorithm.

    Parameters:
    n (int): The upper limit for counting prime numbers.

    Returns:
    int: The count of prime numbers less than or equal to n.
    """
    if n < 2:
        return 0

    prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if prime[p]:
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1

    return sum(1 for p in range(2, n + 1) if prime[p])

