def group_points_by_quadrant(coordinates):
    """
    Groups points into four quadrants based on their coordinates.

    Parameters:
    coordinates (list of tuples): A list where each tuple contains two integers representing the x and y coordinates of a point.

    Returns:
    dict: A dictionary with keys as integers (1, 2, 3, 4) and values as lists of tuples, where each tuple represents a point in the corresponding quadrant.
    """
    quadrants = {1: [], 2: [], 3: [], 4: []}

    for x, y in coordinates:
        if x > 0 and y > 0:
            quadrants[1].append((x, y))
        elif x < 0 and y > 0:
            quadrants[2].append((x, y))
        elif x < 0 and y < 0:
            quadrants[3].append((x, y))
        elif x > 0 and y < 0:
            quadrants[4].append((x, y))

    return quadrants

