def fibonacci_memo(n, memo=None):
    """
    Computes the nth Fibonacci number using recursion and memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence to compute.
    memo (dict, optional): A dictionary to store previously computed Fibonacci numbers.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    if n == 1:
        return 1
    memo[n] = fibonacci_memo(n - 1, memo) + fibonacci_memo(n - 2, memo)
    return memo[n]

def find_max(arr):
    """
    Returns the maximum element in the list arr.
    If arr is empty, returns None.
    If arr contains only one element, returns that element.
    """
    if not arr:
        return None
    elif len(arr) == 1:
        return arr[0]
    else:
        return max(arr)

