def find_longest_balanced_substring(S: str) -> str:
    """
    Finds the longest contiguous substring in a binary string S that has an equal number of 0s and 1s.
    If multiple substrings of the same maximum length exist, returns the lexicographically smallest one.
    If no such substring exists, returns an empty string.
    """
    balance_index = {0: -1}
    balance = 0
    max_length = 0
    result = ""

    for i, char in enumerate(S):
        if char == '0':
            balance -= 1
        else:
            balance += 1

        if balance in balance_index:
            current_length = i - balance_index[balance]
            if current_length > max_length or (current_length == max_length and S[balance_index[balance]+1:i+1] < result):
                max_length = current_length
                result = S[balance_index[balance]+1:i+1]
        else:
            balance_index[balance] = i

    return result

def is_balanced(s: str) -> bool:
    """
    Determines if the input string of brackets is balanced.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is balanced, False otherwise.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)
    return not stack

