def shunting_yard(expression):
    """
    Evaluates a mathematical expression using the Shunting Yard algorithm.

    :param expression: A string representing a valid mathematical expression.
    :return: A float representing the result of the evaluated expression.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output_queue = []
    operators_stack = []

    tokens = expression.replace('(', ' ( ').replace(')', ' ) ').split()

    for token in tokens:
        if token.isnumeric():
            output_queue.append(float(token))
        elif token == '(':
            operators_stack.append(token)
        elif token == ')':
            while operators_stack and operators_stack[-1] != '(':
                output_queue.append(operators_stack.pop())
            operators_stack.pop()
        else:
            while (operators_stack and operators_stack[-1] != '(' and
                   precedence[operators_stack[-1]] >= precedence[token]):
                output_queue.append(operators_stack.pop())
            operators_stack.append(token)

    while operators_stack:
        output_queue.append(operators_stack.pop())

    return evaluate_reverse_polish_notation(output_queue)


def evaluate_reverse_polish_notation(rpn):
    """
    Evaluates an expression in Reverse Polish Notation (RPN).

    :param rpn: A list of tokens representing an expression in RPN.
    :return: A float representing the result of the evaluated RPN expression.
    """
    stack = []

    for token in rpn:
        if isinstance(token, float):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)

    return stack[0]


