def classify_triangle(a: float, b: float, c: float) -> str:
    """
    Classify the type of triangle based on its side lengths.

    Parameters:
    a (float): Length of the first side.
    b (float): Length of the second side.
    c (float): Length of the third side.

    Returns:
    str: Description of the triangle type or if it's not a triangle.
    """
    if a + b > c and a + c > b and b + c > a:
        if a == b == c:
            return 'Equilateral triangle'
        elif a == b or b == c or a == c:
            return 'Isosceles triangle'
        else:
            return 'Scalene triangle'
    else:
        return 'Not a triangle'

