def find_largest_prime(n):
    """
    Returns the largest prime number less than or equal to n.
    If no such prime number exists, returns None.

    :param n: Integer, the upper limit to search for the largest prime.
    :return: Integer or None, the largest prime number <= n or None if no prime exists.
    """
    def is_prime(num):
        """
        Checks if a number is prime.

        :param num: Integer, the number to check for primality.
        :return: Boolean, True if num is prime, False otherwise.
        """
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    for i in range(n, 1, -1):
        if is_prime(i):
            return i
    return None

def sort_descending(numbers):
    """
    Sorts the list of numbers in descending order without using any built-in sort functions.

    :param numbers: List of integers to be sorted.
    :return: The sorted list in descending order.
    """
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if numbers[i] < numbers[j]:
                numbers[i], numbers[j] = numbers[j], numbers[i]
    return numbers

